/*
 * Copies i18n/*.json into i18n/bundle.js so the site also works when
 * index.html is opened by double-click (browsers block fetch() on file://).
 *
 * Run after editing any translation:   node tools/build-i18n-bundle.js
 * Served over http(s), the site reads the JSON files directly and ignores the bundle.
 */
const fs = require("fs");
const path = require("path");

const dir = path.join(__dirname, "..", "i18n");
const bundle = {};

for (const file of fs.readdirSync(dir).filter((name) => name.endsWith(".json")).sort()) {
  bundle[path.basename(file, ".json")] = JSON.parse(fs.readFileSync(path.join(dir, file), "utf8"));
}

const banner = "/* GENERATED by tools/build-i18n-bundle.js. Do not edit: edit the .json files. */\n";
fs.writeFileSync(path.join(dir, "bundle.js"), banner + "window.__I18N_BUNDLE__ = " + JSON.stringify(bundle) + ";\n");
console.log("i18n/bundle.js written:", Object.keys(bundle).join(", "));
